import heapq


def _dependency_solver(data, preference, name_order):
    packages = data["packages"]
    roots = data["roots"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    names = sorted(packages, reverse=(name_order == "descending"))
    best_key = None
    best = None

    def active_deps(row):
        return [d for d in row.get("deps", [])
                if not d.get("feature") or d["feature"] in features]

    def acyclic(chosen):
        edges = {name: [d["name"] for d in active_deps(row)]
                 for name, row in chosen.items()}
        done, visiting = set(), set()

        def visit(name):
            if name in visiting:
                return False
            if name in done:
                return True
            visiting.add(name)
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            visiting.remove(name)
            done.add(name)
            return True

        return all(visit(name) for name in edges)

    def search(chosen, pending):
        nonlocal best_key, best
        if not pending:
            if not acyclic(chosen):
                return
            vector = tuple(chosen[n]["version"] if n in chosen else -1
                           for n in names)
            key = vector if preference == "maximum" else tuple(-v for v in vector)
            if best_key is None or key > best_key:
                best_key, best = key, {n: r["version"] for n, r in chosen.items()}
            return
        name, low, high = pending[-1]
        rest = pending[:-1]
        if name in chosen:
            version = chosen[name]["version"]
            if low <= version <= high:
                search(chosen, rest)
            return
        rows = [r for r in packages[name]
                if low <= r["version"] <= high
                and r["version"] not in blocked.get(name, [])
                and (name not in pins or r["version"] == pins[name])]
        for row in rows:
            newer = dict(chosen)
            newer[name] = row
            added = [(d["name"], d["min"], d["max"])
                     for d in active_deps(row)]
            search(newer, rest + added)

    pending = [(name, bounds[0], bounds[1])
               for name, bounds in roots.items()]
    search({}, pending)
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n, d):
        if mode == "half_up":
            return (n + d // 2) // d
        return n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _quota_jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for subset in combinations(jobs, k):
        ids = [job["id"] for job in subset]
        idset = set(ids)
        if idset & blocked or not mandatory <= idset:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not (bounds[0] <= counts.get(group, 0) <= bounds[1])
               for group, bounds in quotas.items()):
            continue
        # Half-open intervals: release endpoints before admitting new intervals.
        events = []
        for job in subset:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        valid = True
        for _, delta in sorted(events, key=lambda event: (event[0], event[1])):
            active += delta
            if active > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(job["value"] for job in subset)
        ordered_ids = sorted(ids)
        if (best_value is None or value > best_value
                or (value == best_value and ordered_ids > best_ids)):
            best_value, best_ids = value, ordered_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit.get(source, 0)
    start = data["start"]
    coupons = data["coupons"]
    initial = (source, initial_mask, coupons)
    distances = {initial: start}
    queue = [(start, source, initial_mask, coupons)]

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            next_mask = mask | bit.get(edge["v"], 0)
            for duration, next_remaining in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, edge["v"], next_mask, next_remaining))
    return {"arrival": None}


